/* Guidance for bank sales milestones; Bank process statuses stay in Pengajuan. */
let bankStageContext='';
function bankCanonicalStageName(name){const id=db.config?.bankingStageAliases?.[name];return stageDefs().find(s=>s.id===id)?.name||name}
function bankStageFor(o){return stageDefs().find(s=>s.id===o?.stageId)||stageDefs().find(s=>s.name===o?.stage)}
function bankStageProductHint(s,o){const product=masters().products.find(p=>p.name===o?.product);return product?.category==='Kredit'?s?.creditHint:product&&['Dana','Layanan lain'].includes(product.category)?s?.fundingHint:[s?.creditHint,s?.fundingHint].filter(Boolean).join(' ')}
function bankStageGuide(s,o){if(!s)return '';const hint=bankStageProductHint(s,o);return '<div class="bank-stage-guide"><strong>'+E(s.name)+'</strong>'+(s.description?'<p>'+E(s.description)+'</p>':'')+(s.exitCriteria?'<p><b>Tindak lanjut:</b> '+E(s.exitCriteria)+'</p>':'')+(hint?'<p>'+E(hint)+'</p>':'')+(s.type==='won'?'<small>Berhasil dicatat dari hasil yang sudah dikonfirmasi. CRM tidak menjalankan approval, pencairan atau pembukaan rekening Bank.</small>':'<small>SLA tahap baru: '+E(s.sla)+' hari kalender, sesuai Pengaturan. Tahap dapat dilewati bila tidak relevan dengan produk; catat konteksnya.</small>')+'</div>'}
const bankStageFieldsBefore=stageChangeFields;
stageChangeFields=function(s){return bankStageGuide(s,opp(bankStageContext))+bankStageFieldsBefore(s)};
const bankStageChangeBefore=changeStage;
changeStage=function(id){bankStageContext=id;return bankStageChangeBefore(id)};
closeOpp=changeStage;
function bankSelectStage(id,stageId){changeStage(id);const form=document.querySelector('#form');if(form?.elements.stageId&&[...form.elements.stageId.options].some(o=>o.value===stageId)){form.elements.stageId.value=stageId;updateStageChangeFields()}}
function bankStageTask(id){const o=opp(id);if(!o||!mine(o))return;newTask(o.profile,o.id,o.lead||'');const input=document.querySelector('#form [name="purpose"]'),s=bankStageFor(o);if(input)input.value='Tindak lanjut '+(s?.name||o.stage)+': '+(s?.exitCriteria||o.need||o.name)}
function bankStagePanel(o){const current=bankStageFor(o),process=stageDefs().filter(s=>s.type==='process'&&s.active),index=process.findIndex(s=>s.id===current?.id),next=index>=0?process[index+1]:null,apps=db.applications.filter(a=>a.opp===o.id&&mine(a)),active=o.outcome==='Aktif';return '<section class="panel bank-opportunity-stages"><div class="bank-stage-heading"><div><small>PROSES PEMASARAN BANKING</small><h2>Tahap & tindak lanjut</h2></div>'+badge(current?.name||o.stage)+'</div><ol class="bank-stage-path" aria-label="Tahap proses Opportunity">'+process.map(s=>'<li><button '+(!active?'disabled':'')+' '+(s.id===current?.id?'aria-current="step"':'')+' class="'+(s.id===current?.id?'active':'')+'" onclick="bankSelectStage('+E(JSON.stringify(o.id))+','+E(JSON.stringify(s.id))+')">'+E(s.name)+'</button></li>').join('')+'</ol>'+bankStageGuide(current,o)+detailFacts([['Masuk tahap',o.entered?fmt(o.entered):'Belum tercatat'],['SLA record saat ini',String(stageLimit(o))+' hari kalender'],['Pengajuan tertaut',String(apps.length)]])+'<div class="actions">'+(active?btn('Buat Task',"bankStageTask("+E(JSON.stringify(o.id))+")",true)+(next?btn('Lanjut ke tahap berikutnya',"bankSelectStage("+E(JSON.stringify(o.id))+','+E(JSON.stringify(next.id))+")"):''):'')+(apps.length?btn('Lihat Pengajuan',"openApplication("+E(JSON.stringify(apps[0].id))+")"):active?btn('Tautkan Pengajuan',"applicationForm("+E(JSON.stringify(o.id))+")"):'')+'</div><p class="hint">Survey, analisa, approval dan pencairan mengikuti catatan di Pengajuan. Mengubah tahap Opportunity tidak otomatis mengubah status tersebut. Tidak semua produk dana/layanan memerlukan Survey atau Pengajuan kredit.</p></section>'}
function bankTaskClosureGuide(){const f=document.querySelector('#form');if(!f?.elements.closeStage||!f.elements.reference)return;const s=stageDefs().find(s=>s.name===f.elements.closeStage.value);f.elements.reference.required=!!(s?.requiresReference&&f.elements.follow.value==='Tutup opportunity');const root=document.querySelector('#closeFields');let info=root?.querySelector('.bank-stage-guide');if(info)info.remove();root?.insertAdjacentHTML('afterbegin',bankStageGuide(s,opp(bankStageContext)));}
const bankToggleResultBefore=toggleResultFields;
toggleResultFields=function(){bankToggleResultBefore();bankTaskClosureGuide()};
const bankActivityBefore=activityForm;
activityForm=function(id){bankStageContext=task(id)?.opp||'';bankActivityBefore(id);const select=document.querySelector('#form [name="closeStage"]');if(select){select.addEventListener('change',bankTaskClosureGuide);bankTaskClosureGuide()}};
const bankStageContentBefore=renderContent;
renderContent=function(){if(stageFilter)stageFilter=bankCanonicalStageName(stageFilter);bankStageContentBefore();if(view==='Opportunity detail'){const o=opp(focus),app=document.querySelector('#app');if(o&&mine(o)&&app&&!app.querySelector('.bank-opportunity-stages')){const hero=app.querySelector(':scope>.panel');if(hero)hero.insertAdjacentHTML('afterend',bankStagePanel(o));else app.insertAdjacentHTML('afterbegin',bankStagePanel(o));}}if(view==='Peluang'){const app=document.querySelector('#app');if(app&&!app.querySelector('.bank-stage-overview')){const intro=app.querySelector('.intro');intro?.insertAdjacentHTML('afterend','<details class="panel bank-stage-overview"><summary>Panduan tahap Opportunity banking</summary><p>Tahap adalah milestone pemasaran. Pilih tahap sesuai perkembangan sebenarnya; Survey dapat dilewati bila tidak relevan. Status pengajuan tetap ditrack terpisah.</p><div class="bank-stage-overview-grid">'+stageDefs().filter(s=>s.active).map(s=>'<article><strong>'+E(s.name)+'</strong><p>'+E(s.description||'Panduan tahap dapat diisi di Pengaturan.')+'</p><small>'+E(s.exitCriteria||'')+'</small></article>').join('')+'</div></details>')}}};
if(typeof authUser!=='undefined'&&authUser&&!choosingBranch)renderContent();
